/// Seeds the bundled curriculum in bounded chunks.
///
/// A single 3.7k-row batch marshals every row across the platform
/// channel before any of it is written, which blocks the UI thread for
/// long enough to drop the first frames. Chunking plus an explicit yield
/// between chunks keeps the splash animating while the seed runs.
///
/// [onProgress] receives a 0..1 value so the UI can show real progress
/// instead of an indefinite spinner.
Future<void> seedDatabase(
  Database db, {
  void Function(double progress)? onProgress,
  int chunkSize = 200,
}) async {
  const tables = <String, List<Map<String, Object>>>{
    'subjects': curriculumSubjects,
    'lessons': curriculumLessons,
    'topics': curriculumTopics,
    'quiz_questions': curriculumQuizQuestions,
    'quiz_options': curriculumQuizOptions,
    'formulas': curriculumFormulas,
    'programming_references': curriculumProgrammingReferences,
  };
  final total = tables.values.fold<int>(0, (sum, rows) => sum + rows.length);
  var written = 0;
  for (final entry in tables.entries) {
    final rows = entry.value;
    for (var start = 0; start < rows.length; start += chunkSize) {
      final end =
          (start + chunkSize) < rows.length ? start + chunkSize : rows.length;
      final batch = db.batch();
      for (final row in rows.sublist(start, end)) {
        batch.insert(entry.key, row);
      }
      await batch.commit(noResult: true);
      written += end - start;
      onProgress?.call(total == 0 ? 1 : written / total);
      // Yield so the event loop can paint between chunks.
      await Future<void>.delayed(Duration.zero);
    }
  }
}
